def tau(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def check_solution(k):
    """Checks if tau(2*k^3) == 2*k for a given positive integer k."""
    if k <= 0:
        return False

    n = 2 * (k**3)
    lhs = tau(n)
    rhs = 2 * k

    return lhs == rhs

